UPDATE aid_entries SET information = '<p>Bogotá. Confirmar puntos en idcbis.org.co/banco-distrital-de-sangre<br>El Banco Distrital de Sangre IDCBIS ha enviado 89 unidades de componentes sanguíneos a Quibdó e invita a donar.<br>Las autoridades invitan a la ciudadanía a donar para mantener las reservas y continuar atendiendo a los pacientes en las zonas afectadas. De domingo a domingo de 8:00 a.m. a 5:00 p.m. Revisar idcbis.org.co/banco-distrital-de-sangre para confirmar los puntos, ya que constantemente los están actualizando y ubican jornadas de donación adicionales.<br>Viernes 14 de agosto: Secretaría Distrital de Salud, 8:00 a.m. a 5:00 p.m.<br>Sábado 15 de agosto: Centro Comercial Plaza Imperial, 11:00 a.m. a 6:00 p.m.<br>Domingo 16 de agosto: Iglesia María Madre Admirable, 8:00 a.m. a 3:30 p.m.; Parque Timiza, 9:00 a.m. a 4:30 p.m.; Parque San Andrés, 9:00 a.m. a 4:30 p.m.<br>Lunes 17 de agosto: Parque El Tunal, 9:30 a.m. a 5:30 p.m.; Parque Gilma Jiménez, 9:00 a.m. a 4:30 p.m.; Centro Comercial Plaza Imperial, 10:30 a.m. a 6:00 p.m.</p>', updated_at = datetime('now') WHERE id = 124 AND source LIKE '%14 de agosto de 2026%';
